#pragma once
#include <cstddef>
#include <cstdint>
#include <span>
#include <stdexcept>
#include <vector>
struct saddle_point_t {
    std::size_t row, column;
};
// Coordinates are one-based. Caller releases the returned record with
// free_saddle_points.
struct saddle_points_t {
    std::size_t count = 0;
    std::vector<saddle_point_t> points;
};
saddle_points_t *saddle_points(std::size_t rows, std::size_t columns,
                               std::span<const std::uint8_t> matrix);
inline saddle_points_t *saddle_points(std::size_t rows, std::size_t columns,
                                      std::nullptr_t) {
    return saddle_points(rows, columns, std::span<const std::uint8_t>{});
}
template <std::size_t R, std::size_t C>
saddle_points_t *saddle_points(std::size_t rows, std::size_t columns,
                               const std::uint8_t (&matrix)[R][C]) {
    if (rows != R || columns != C)
        throw std::invalid_argument("Matrix dimensions disagree");
    std::vector<std::uint8_t> flat;
    flat.reserve(R * C);
    for (const auto &row : matrix)
        flat.insert(flat.end(), row, row + C);
    return saddle_points(rows, columns, std::span<const std::uint8_t>{flat});
}
void free_saddle_points(saddle_points_t *points);

