#include "saddle_points.h"
#include <limits>
#include <memory>
static bool is_greatest_in_row(std::size_t row, std::size_t column, std::size_t columns,
                               std::span<const std::uint8_t> matrix) {
    const auto candidate = matrix[row * columns + column];
    for (std::size_t c = 0; c < columns; ++c)
        if (matrix[row * columns + c] > candidate)
            return false;
    return true;
}
static bool is_least_in_column(std::size_t row, std::size_t column, std::size_t rows,
                               std::size_t columns,
                               std::span<const std::uint8_t> matrix) {
    const auto candidate = matrix[row * columns + column];
    for (std::size_t r = 0; r < rows; ++r)
        if (matrix[r * columns + column] < candidate)
            return false;
    return true;
}
saddle_points_t *saddle_points(std::size_t rows, std::size_t columns,
                               std::span<const std::uint8_t> matrix) {
    auto result = std::make_unique<saddle_points_t>();
    if (matrix.empty() || rows == 0 || columns == 0)
        return result.release();
    if (rows > std::numeric_limits<std::size_t>::max() / columns ||
        rows * columns != matrix.size())
        throw std::invalid_argument("Matrix dimensions disagree");
    for (std::size_t row = 0; row < rows; ++row)
        for (std::size_t column = 0; column < columns; ++column)
            if (is_greatest_in_row(row, column, columns, matrix) &&
                is_least_in_column(row, column, rows, columns, matrix))
                result->points.push_back({row + 1, column + 1});
    result->count = result->points.size();
    return result.release();
}
void free_saddle_points(saddle_points_t *points) { delete points; }

