int main(void) {
    UNITY_BEGIN();

    RUN_TEST(test_single_saddle_point);
    RUN_TEST(test_empty_matrix_has_no_saddle_points);
    RUN_TEST(test_lack_of_saddle_points_when_there_are_none);
